// Compile RhcSimulator.sol and write backend/rhc_sim_bytecode.py.
// Usage: NODE_PATH=<dir with node_modules/solc@0.8.26> node backend/contracts/build_simulator.js
// The generated file records the source SHA-256 so tests can detect a stale build.
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const solc = require("solc");

const src = fs.readFileSync(path.join(__dirname, "RhcSimulator.sol"), "utf8");
const input = {
  language: "Solidity",
  sources: { "RhcSimulator.sol": { content: src } },
  settings: { optimizer: { enabled: true, runs: 200 }, viaIR: true, evmVersion: "cancun",
              outputSelection: { "*": { "*": ["evm.deployedBytecode.object", "abi"] } } },
};
const out = JSON.parse(solc.compile(JSON.stringify(input)));
const errs = (out.errors || []).filter((e) => e.severity === "error");
if (errs.length) { console.error(errs.map((e) => e.formattedMessage).join("\n")); process.exit(1); }
(out.errors || []).forEach((e) => console.warn(e.formattedMessage));
const c = out.contracts["RhcSimulator.sol"]["RhcSimulator"];
const runtime = c.evm.deployedBytecode.object;
const sha = crypto.createHash("sha256").update(src).digest("hex");
const py = `"""GENERATED by backend/contracts/build_simulator.js - do not edit.
Runtime bytecode of contracts/RhcSimulator.sol (solc ${solc.version()}, viaIR, optimizer 200 runs, cancun).
Used only via eth_call state overrides; never deployed."""
SOURCE_SHA256 = "${sha}"
SOLC_VERSION = "${solc.version()}"
RUNTIME = "0x${runtime}"
`;
fs.writeFileSync(path.join(__dirname, "..", "rhc_sim_bytecode.py"), py);
console.log("runtime bytes:", runtime.length / 2, "sha256:", sha);
